import { cn } from "@/lib/cn";

/**
 * The official bycauazin sticker logo (spiral ribbon) in nuCorre colors: outline creme #faf3e8,
 * ribbon navy #253b57, inside pink #f4a6c1. Generated by ../landing-page/brand/make-logo.mjs
 * (see routine-front/README). On the light page outline and ribbon swap (/logo-sticker-light.svg).
 * - onBrand: creme outline whatever the theme, for navy surfaces (the opening).
 * Height comes from className (h-9 by default); the width follows the ribbon (826 × 1760).
 * When the SVGs change, bump ?v= (browsers keep them cached).
 */
export function BrandMark({ onBrand = false, className }) {
  const size = cn(!/(^|\s)h-/.test(className ?? "") && "h-9", "w-auto shrink-0", className);
  if (onBrand) return <img src="/logo-sticker.svg?v=1" alt="" width={17} height={36} className={size} />;
  return (
    <>
      <img src="/logo-sticker-light.svg?v=1" alt="" width={17} height={36} className={cn(size, "dark:hidden")} />
      <img src="/logo-sticker.svg?v=1" alt="" width={17} height={36} className={cn(size, "hidden dark:block")} />
    </>
  );
}

/** Signature shared by every project: <bycauazin/> in Major Mono Display, "by" in the accent. */
export function BrandSignature({ className }) {
  return (
    <b className={cn("brand-signature", className)}>
      <i className="opacity-50">&lt;</i>
      <i className="text-accent-text">by</i>cauazin<i className="opacity-50">/&gt;</i>
    </b>
  );
}

/** "nuCorre" in the wordmark style (.brand-word in index.css: Inter 800). */
export function BrandWord({ className }) {
  return <span className={cn("brand-word", className)}>nuCorre</span>;
}

/** Wordmark: logo + nuCorre, signed <bycauazin/>. */
export function Brand({ className, signature = true, size = "text-[18px]" }) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", className)}>
      <BrandMark />
      <BrandWord className={size} />
      {signature && <BrandSignature className="hidden text-[10.5px] text-faint sm:inline" />}
    </span>
  );
}
